def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 20:
        opp = [h[1] for h in history]
        if opp.count('D') >= 2:
            return 'D'
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    if len(opp) >= 2 and opp[-2:] == ['D', 'D']:
        return 'D'
    if len(opp) >= 4 and opp[-4:].count('D') >= 3:
        return 'D'
    d_rate = opp.count('D') / n
    if d_rate > 0.35:
        return 'D'
    my_last = me[-1]
    if last_opp == 'D':
        recent = opp[-10:]
        if recent.count('D') >= 5:
            return 'D'
        return 'D'
    if last_opp == 'C':
        if d_rate < 0.1:
            return 'C'
        recent = opp[-10:]
        if recent.count('D') >= 4:
            return 'D'
        return 'C'
    return 'C'

